function avatarSrc(id) {
  if (typeof id === "string" && (id.startsWith("data:image") || id.startsWith("http"))) return id;
  const idx = Number(id);
  if (Number.isInteger(idx) && idx >= 0 && idx < AVATAR_IMAGES.length) return AVATAR_IMAGES[idx];
  return null;
}

